startGuideActionMenu: "Seleccionar menú",
startGuideActivity: "Las actividades son las tareas planificadas de los proyectos. <br/>Se puede desglosar la estructura del trabajo de un proyecto. <br/>No hay límite de niveles de estructura (fases / sub-fases / tareas / sub-tareas …)",
startGuideAffectation: "Un recurso debe de estar dedicado a un proyecto para poder ver sus ítems.<br/>La dedicación a un proyecto automáticamente también da visibilidad a ítems de sus sub-proyectos",
startGuideClient: "Clientes son las entidades para las que se realiza el trabajo.<br/>Pueden ser tanto internos como externos a la organización.",
startGuideContact: "Contactos son las personas con las que mantenemos relación y que pertenecen a las entidades clientes.",
startGuideFooter: "Principales funcionalidades&#58; <br/>Una vez le sean familiares podrá ir descubriendo los demás módulos para la gestión detallada de proyectos.",
startGuideImputation: "Los recursos introducen su trabajo real en la pantalla de registro de tiempos correspondiente día a día y actividad a actividad.<br/> La re-estimación del trabajo « izqda » permite la actualización del proyecto según el progreso real.",
startGuideIntro: "Esto es una pequeña ayuda en los primeros pasos con ProjeQtOr.<br>Seguir las indicaciones para configurar los módulos iniciales.<br>Para más ayuda se puede pulsar [F1] y acceder al manual en línea en el que encontrar más información.<br>Regresar a la página Para Hoy para acceder a esta guia de inicio.",
startGuideMilestone: "Hitos son las fechas claves de un proyecto.<br/>Pueden definirse como 'entrantes' (hitos fijos) o como 'entregables' (hitos flotantes).",
startGuidePlanning: "La planificación se muestra como cronograma (diagrama de Gantt).<br/>Para planificar actividades se deben asignar recursos y definir el trabajo a realizar ya que es generada según éste.<br/>Se pueden definir las relaciones entre tareas (enlaces precedentes) e hitos...<br/>Se puede posteriormente consultar la planificación de ejecución teniendo en cuenta todos las limitaciones de los recursos&#44; como por ejemplo su disponibilidad.",
startGuideProject: "El proyecto es el ítem principal en ProjeQtOr.<br/>Cada ítem está relacionado con un proyecto.<br/>Los derechos de acceso también se definen a nivel de proyecto.",
startGuideResource: "Los recursos son las personas que trabajan sobre las tareas.<br/>Si se marca la opción « es un usuario »&#44; el recurso también podrá utilizar la plataforma ProjeQtOr.",
startGuideTicket: "Los tickets permiten realizar el seguimiento de cada evento puntual relacionado con el proyecto&#44; como por ejemplo errores&#44; bugs&#44; o cualquier tipo de solicitud<br/>Pueden ser fácilmente convertidos o copiados como actividades cuando se necesite sin tener que re-escribir la información y manteniendo el enlace con su solicitud original.",
startGuideTitle: "Manual de usuario",
startGuideUser: "Usuarios son las personas que utilizan la aplicación. <br/> Deben de tener un perfil que determina los permisos de acceso a los módulos.",
