tooltip: "tooltip",
tooltipAddInTextBoxNotificationDefinition: "Coloque el cursor donde desea insertar el campo y haga clic aquí",
tooltipAddPseudoUsers: "Email addresses that do not correspond to a known user will automatically generate &#34closed&#34 (idle) users.<br/>These pseudo-users will not be able to log in but will be able to receive emails.<br/>This system allows you to record the sender and subscribers (copy recipients).",
tooltipAddToFollowUp: "Systematically include the sender and recipients of the email in the follow up of the ticket created or note added by this email. This includes the main recipients (except the one corresponding to the inbox) and the copy recipients.",
tooltipAlertValue: "Recordatorio",
tooltipAllowRedution: "When reduction is allowed you can & # 58 </br> - remove items from this project </br> - move items outside of this project",
tooltipCommandOnValidWork: "Activates treatment of the validated work based on the sum of the work of the project client orders <br/>otherwise it will be calculated on the sum of the validated work of the activities",
tooltipExcludeFromGlobalPlanning: "No muestre los elementos &#34no planificables&#34 para este proyecto en la vista de planificación global.<br/> Esto significa que solo los elementos &#34estándar #34 de planificación se mostrarán &#44excluyendo acciones&#44 decisiones&#44 entregas &#44 ...",
tooltipFixPerimeter: "When project perimeter is fixed you can't &#58 </br> - add new elements to this project</br> - delete elements from this project</br> - move elements to this project</br> - move elements from this project",
tooltipFixPlanning: "Cuando un proyecto tiene &#planificación fija&#34 nunca se vuelve a calcular <br/> Significa que la planificación siempre será la misma sin importar lo que haga en otros proyectos <br/> Esto puede llevar a la falta de consistencia de las dependencias.",
tooltipFixPlanningActivity: "When an activity has &#34fix planning&#34 it is never re-calculated<br/>It means the planning will always be the same whatever you do on other projects<br/>This may lead to dependencies unconsistency.",
tooltipIndivisibility: "Make the activity not splitted for each assignment.<br/> The planning will be done on contiguous days with an availability greater than or equal to the minimum threshold.",
tooltipIsLeadProject: "Projects of this type do not contain activities. <br/>They are intended to contain sub-projects that will contain the activities. <br/>However&#44 they may contain meetings or milestones.",
tooltipLeaveContractStartDate: "If you change this date <br/> Do not forget to check that there are validated leaves for the new date",
tooltipLevelNote: "Se nivelará la nota final a la correspondiente&#44 cualquiera que sea la suma de notas ponderadas",
tooltipMinimumThreshold: "Minimum daily threshold for planning. <br/> Activity will only be scheduled on a given day if daily availability is greater than or equal to this threshold.",
tooltipNotifiable: "Elija el elemento de notificación obligatoria para establecer la regla de generación de notificaciones",
tooltipNotificationDaysBefore: "Número de días antes de la fecha de referencia para la cual se generarán las notificaciones.<br/>Notificación anticipada Ex = 10 - Diario = Seleccionado<br/>Se emitirá una notificación diariamente comenzando 10 días antes de la fecha de referencia. <br/>Si es negativo => La generación de notificaciones solo comienza DESPUÉS de la fecha de referencia.",
tooltipNotificationEveryDay: "Si se selecciona <br/> Se generarán notificaciones proactivas cada día abierto",
tooltipNotificationEveryMonth: "Si se selecciona <br/> Las notificaciones correspondientes a la regla se generarán todos los meses",
tooltipNotificationEveryWeek: "Si está seleccionado <br/>Notificaciones sensibles se generarán semanalmente",
tooltipNotificationEveryYear: "Si está seleccionado <br/>Las notificaciones correspondientes a la regla se generarán todos los años",
tooltipNotificationFixedDay: "Si no está en blanco <br/>Las notificaciones correspondientes a la regla se generarán en el día seleccionado",
tooltipNotificationFixedMonth: "Si no está en blanco <br/>Las notificaciones correspondientes a la regla se generarán en el mes seleccionado",
tooltipNotificationGenerateBefore: "La notificación se generará este número de días antes de la fecha de notificación calculada real.",
tooltipNotificationGenerateBeforeInMin: "Activo solo si la fecha de referencia es Fecha y hora <br/>La notificación se generará este número de minutos antes de la fecha de notificación calculada.",
tooltipNotificationMenu: "Seleccione el elemento de notificación obligatoria que lee la regla de generación de las notificaciones",
